def count_pairs(nums, target):
    # Brute-force approach: check all pairs where 0 ≤ i < j < len(nums)
    count = 0
    n = len(nums)
    for i in range(n):
        for j in range(i+1, n):
            # Check if the sum of the current pair is less than target
            if nums[i] + nums[j] < target:
                count += 1
    return count
